} from "./response";
import type { TV3AuditLog, TV3Authentication } from "./types";

type TV3Schema = z.ZodTypeAny;
type MaybePromise<T> = T | Promise<T>;

export type TV3AuthMode = "none" | "session" | "apiKey" | "both";

export type TV3Schemas = {
  body?: TV3Schema;
  query?: TV3Schema;
  params?: TV3Schema;
};

export type TV3ParsedInput<S extends TV3Schemas | undefined> = S extends object
  ? {
      [K in keyof S as NonNullable<S[K]> extends TV3Schema ? K : never]: z.infer<NonNullable<S[K]>>;
    }
  : Record<string, never>;

export type TV3HandlerParams<TParsedInput = Record<string, never>, TProps = unknown> = {
  req: NextRequest;
  props: TProps;
  authentication: TV3Authentication;
  auditLog?: TV3AuditLog;
  parsedInput: TParsedInput;
  requestId: string;
  instance: string;
};

export type TWithV3ApiWrapperParams<S extends TV3Schemas | undefined, TProps = unknown> = {
  auth?: TV3AuthMode;
  schemas?: S;
  rateLimit?: boolean;
  customRateLimitConfig?: TRateLimitConfig;
  /**
   * The largest request body this route reads, in bytes. Defaults to `DEFAULT_REQUEST_BODY_LIMIT_BYTES`
   * (2 MB). Applies to declared and undeclared bodies alike, and is enforced while reading, so a body
   * sent without a `Content-Length` header is cut off at the limit rather than buffered whole.
   *
   * Raise it only for a route that genuinely takes a file-sized body, and keep it below Next's
   * `proxyClientMaxBodySize` (`next.config.mjs`). The patched Next (`patches/next@16.4.1.patch`) no longer
   * clones bodies for the proxy, but without the patch Next truncates a longer body before this reader sees
   * it, so the caller would get a 400 for malformed JSON instead of a 413.
   */
  bodyLimitBytes?: number;
  /**
   * Caps how many requests to this route one server process handles at once; the next one gets a 503
   * `capacity_reached` with `Retry-After`. The slot is taken after authentication and rate limiting but
   * **before the body is read**, so it also bounds the memory spent parsing large bodies, and it is held
   * until the response body is fully sent or cancelled, so a streamed response keeps its slot for as
   * long as it runs, or until the client disconnects. Share one `ConcurrencyLimiter` per route, created at
   * module scope.
   *
   * With `maxPerKey` on the limiter, one caller (session user or API key) can hold only that many slots;
   * the next of theirs gets a 429 with `Retry-After` instead.
   *
   * Rate limiting runs first on purpose, so a rate-limited caller never holds a slot; the price is that
   * a refusal still spends one rate-limit token.

import { z } from "zod";
import { withV3ApiWrapper } from "@/app/api/v3/lib/api-wrapper";
import { ZV3EmptyQuery } from "@/app/api/v3/lib/schemas";
import { archiveV3Survey } from "../../lib/operations";

const surveyParamsSchema = z.object({
  surveyId: z.cuid2(),
});

export const POST = withV3ApiWrapper({
  auth: "both",
  action: "archived",
  targetType: "survey",
  schemas: {
    params: surveyParamsSchema,
    // Single-survey endpoints locate the survey by its globally-unique id; reject stray query params.
    query: ZV3EmptyQuery,
  },
  handler: async ({ parsedInput, authentication, requestId, instance, auditLog }) => {
    return await archiveV3Survey({
      surveyId: parsedInput.params.surveyId,
      authentication,
      requestId,
      instance,
      auditLog,
    });
  },
});

/**
 * GET /api/v3/responses — list responses for a workspace, newest first.
 *
 * Raw `searchParams` rather than a wrapper-parsed schema, matching the surveys list: the query
 * carries bracket-style `filter[...]` families that a flat Zod object cannot describe, and the
 * cursor's 400 has to name `cursor` specifically rather than fail as a generic parse error.
 *
 * A thin adapter on purpose: the orchestration lives in the operation and the service, which the MCP
 * server also calls directly with no wrapper around them.
 */
import { withV3ApiWrapper } from "@/app/api/v3/lib/api-wrapper";
import { ZV3EmptyQuery } from "@/app/api/v3/lib/schemas";
import { withV3ResponsesReadMetrics } from "./lib/metrics";
import { createV3Response, listV3Responses } from "./lib/operations";
import { ZV3CreateResponseBody } from "./lib/schemas";

export const GET = withV3ResponsesReadMetrics(
  "list",
  withV3ApiWrapper({
    auth: "both",
    handler: async ({ req, authentication, requestId, instance }) =>
      listV3Responses({
        searchParams: new URL(req.url).searchParams,
        authentication,
        requestId,
        instance,
      }),
  })
);

/**
 * POST /api/v3/responses — record a real submission.
 *
 * The workspace is resolved from the body's `surveyId`, never supplied, so the caller cannot choose
 * the scope it is authorized against. An empty strict query means any query parameter is a 400.
 */
export const POST = withV3ApiWrapper({
  auth: "both",
  action: "created",
  targetType: "response",
  schemas: { body: ZV3CreateResponseBody, query: ZV3EmptyQuery },
  handler: async ({ authentication, parsedInput, auditLog, requestId, instance }) =>
    createV3Response({
      authentication,
      body: parsedInput.body,
      auditLog,
      requestId,
      instance,
    }),
});

"use server";

import { z } from "zod";
import { ZId } from "@formbricks/types/common";
import { ResourceNotFoundError } from "@formbricks/types/errors";
import { assertCan } from "@/lib/authorization";
import { generateWebhookSecret } from "@/lib/crypto";
import { capturePostHogEvent } from "@/lib/posthog";
import { assertNewlyAttachedSurveysWorkspaceVisible } from "@/lib/survey/visibility/outbound";
import { authenticatedActionClient } from "@/lib/utils/action-client";
import {
  getOrganizationIdFromWebhookId,
  getOrganizationIdFromWorkspaceId,
  getWorkspaceIdFromWebhookId,
} from "@/lib/utils/helper";
import {
  getWebhook,
  getWebhookWithSecret,
} from "@/modules/api/v2/management/webhooks/[webhookId]/lib/webhook";
import { applyRateLimit } from "@/modules/core/rate-limit/helpers";
import { rateLimitConfigs } from "@/modules/core/rate-limit/rate-limit-configs";
import { withAuditLogging } from "@/modules/ee/audit-logs/lib/handler";
import {
  createWebhook,
  deleteWebhook,
  testEndpoint,
  updateWebhook,
} from "@/modules/integrations/webhooks/lib/webhook";
import { ZWebhookInput } from "@/modules/integrations/webhooks/types/webhooks";

const ZCreateWebhookAction = z.object({
  workspaceId: ZId,
  webhookInput: ZWebhookInput,
  webhookSecret: z.string().optional(),
});

export const createWebhookAction = authenticatedActionClient.inputSchema(ZCreateWebhookAction).action(
  withAuditLogging("created", "webhook", async ({ ctx, parsedInput }) => {
    const organizationId = await getOrganizationIdFromWorkspaceId(parsedInput.workspaceId);
    await assertCan({ type: "user", id: ctx.user.id }, "workspace.write", {
      type: "workspace",
      id: parsedInput.workspaceId,
    });
    await applyRateLimit(rateLimitConfigs.actions.stateMutation, parsedInput.workspaceId);
    await assertNewlyAttachedSurveysWorkspaceVisible(parsedInput.webhookInput.surveyIds ?? []);
    const webhook = await createWebhook(
      parsedInput.workspaceId,
      parsedInput.webhookInput,
      parsedInput.webhookSecret
    );
    ctx.auditLoggingCtx.organizationId = organizationId;
    ctx.auditLoggingCtx.newObject = parsedInput.webhookInput;

    capturePostHogEvent(
      ctx.user.id,
      "integration_connected",
      {
        integration_type: "webhook",
        organization_id: organizationId,
        workspace_id: parsedInput.workspaceId,
      },
      { organizationId, workspaceId: parsedInput.workspaceId }
    );

    return webhook;
  })
);

const ZDeleteWebhookAction = z.object({
  id: ZId,
});

export const deleteWebhookAction = authenticatedActionClient.inputSchema(ZDeleteWebhookAction).action(
  withAuditLogging("deleted", "webhook", async ({ ctx, parsedInput }) => {
    const organizationId = await getOrganizationIdFromWebhookId(parsedInput.id);
    const workspaceId = await getWorkspaceIdFromWebhookId(parsedInput.id);
    await assertCan({ type: "user", id: ctx.user.id }, "workspace.write", {
      type: "workspace",
      id: workspaceId,
    });
    await applyRateLimit(rateLimitConfigs.actions.stateMutation, workspaceId);

    ctx.auditLoggingCtx.organizationId = organizationId;
    ctx.auditLoggingCtx.webhookId = parsedInput.id;
    ctx.auditLoggingCtx.oldObject = { ...(await getWebhook(parsedInput.id)) };

    const result = await deleteWebhook(parsedInput.id);
    return result;
  })
);

const ZUpdateWebhookAction = z.object({
  webhookId: ZId,
  webhookInput: ZWebhookInput,
});

export const updateWebhookAction = authenticatedActionClient.inputSchema(ZUpdateWebhookAction).action(
  withAuditLogging("updated", "webhook", async ({ ctx, parsedInput }) => {
    const organizationId = await getOrganizationIdFromWebhookId(parsedInput.webhookId);
    const workspaceId = await getWorkspaceIdFromWebhookId(parsedInput.webhookId);
    await assertCan({ type: "user", id: ctx.user.id }, "workspace.write", {
      type: "workspace",
      id: workspaceId,
    });
    await applyRateLimit(rateLimitConfigs.actions.stateMutation, workspaceId);

    ctx.auditLoggingCtx.organizationId = organizationId;
    ctx.auditLoggingCtx.webhookId = parsedInput.webhookId;
    const existing = await getWebhook(parsedInput.webhookId);
    ctx.auditLoggingCtx.oldObject = existing;
    await assertNewlyAttachedSurveysWorkspaceVisible(
      parsedInput.webhookInput.surveyIds ?? [],
      existing.ok ? existing.data.surveyIds : []
    );

    const result = await updateWebhook(parsedInput.webhookId, parsedInput.webhookInput);
    ctx.auditLoggingCtx.newObject = await getWebhook(parsedInput.webhookId);
    return result;
  })
);

const ZTestEndpointAction = z.object({
  url: z.string(),
  webhookId: ZId.optional(),
  // Required so the not-yet-created-webhook path has something to authorize against; without it this
  // action did no authorization at all and any logged-in user — including a billing-only member with no
  // product access — could make the server POST a signed test payload to any URL they named.
  workspaceId: ZId,
  secret: z.string().optional(),
});

export const testEndpointAction = authenticatedActionClient
  .inputSchema(ZTestEndpointAction)
  .action(async ({ ctx, parsedInput }) => {
    let secret: string | undefined;

    if (parsedInput.webhookId) {
      await assertCan({ type: "user", id: ctx.user.id }, "workspace.write", {
        type: "workspace",
        id: await getWorkspaceIdFromWebhookId(parsedInput.webhookId),
      });

      const webhookResult = await getWebhookWithSecret(parsedInput.webhookId);
      if (!webhookResult.ok) {
        throw new ResourceNotFoundError("Webhook", parsedInput.webhookId);
      }

      secret = webhookResult.data.secret ?? undefined;
    } else {
      // No webhook yet: authorize against the workspace the webhook is being created in.
      await assertCan({ type: "user", id: ctx.user.id }, "workspace.write", {
        type: "workspace",
        id: parsedInput.workspaceId,
      });

      // New webhook, use the provided secret or generate a new one
      secret = parsedInput.secret ?? generateWebhookSecret();
    }

    await testEndpoint(parsedInput.url, secret);
    return { success: true, secret };
  });

const ZDuplicateWebhookAction = z.object({
  webhookId: ZId,
  workspaceId: ZId,
});

export const duplicateWebhookAction = authenticatedActionClient
  .inputSchema(ZDuplicateWebhookAction)
  .action(
    withAuditLogging("created", "webhook", async ({ ctx, parsedInput }) => {
      const organizationId = await getOrganizationIdFromWebhookId(parsedInput.webhookId);
      const workspaceId = await getWorkspaceIdFromWebhookId(parsedInput.webhookId);
      await assertCan({ type: "user", id: ctx.user.id }, "workspace.write", {
        type: "workspace",
        id: workspaceId,
      });
      await applyRateLimit(rateLimitConfigs.actions.stateMutation, workspaceId);

      const existingResult = await getWebhook(parsedInput.webhookId);
      if (!existingResult.ok) {
        throw new ResourceNotFoundError("Webhook", parsedInput.webhookId);
      }
      const existing = existingResult.data;

      const newName = `Copy of ${existing.name}`;

      const webhook = await createWebhook(workspaceId, {
        name: newName,
        url: existing.url,
        source: "user",
        triggers: existing.triggers,
        surveyIds: existing.surveyIds,
      });

      ctx.auditLoggingCtx.organizationId = organizationId;
      ctx.auditLoggingCtx.newObject = { name: newName };

      capturePostHogEvent(
        ctx.user.id,
        "integration_connected",
        {
          integration_type: "webhook",
          organization_id: organizationId,
          workspace_id: workspaceId,
        },
        { organizationId, workspaceId }
      );

      return webhook;
    })
  );

import { z } from "zod";
import { V3_LIST_DEFAULT_LIMIT, V3_LIST_MAX_LIMIT } from "@/app/api/v3/lib/cursor-pagination";

/**
 * Shared query schema for workspace-scoped v3 reference-list endpoints (action classes, contact
 * attribute keys): a required `workspaceId` plus the standard cursor-pagination `limit` + `cursor`.
 */
export const ZV3WorkspaceListQuery = z
  .object({
    workspaceId: z.cuid2(),
    limit: z.coerce.number().int().min(1).max(V3_LIST_MAX_LIMIT).default(V3_LIST_DEFAULT_LIMIT),
    cursor: z.string().min(1).optional(),
  })
  .strict();

export type TV3WorkspaceListQuery = z.infer<typeof ZV3WorkspaceListQuery>;

/**
 * For operations that accept no query parameters at all. `.strict()` is the point: without it an
 * unrecognized parameter is silently ignored, and a silently-ignored filter returns more data than the
 * caller believes they asked for.
 *
 * Lived in `surveys/schemas.ts` until the response operations needed it too; it was never
 * survey-specific.
 */
export const ZV3EmptyQuery = z.object({}).strict();

"use client";

import { Copy } from "lucide-react";
